1	const KEY='thelopolis-story-archive-v1';
2	let db=loadDB(),activeView='timeline',libraryTab='passages',selectedBoard=[],selectedTimeNodes=[],toastTimer;
3	function loadDB(){try{const d=JSON.parse(localStorage.getItem(KEY));if(d&&Array.isArray(d.stories)&&Array.isArray(d.passages)){d.timeRelations||=[];d.characters||=[];return d}}catch{}return{stories:[],passages:[],characters:[],links:[],timeRelations:[]}}
4	function save(){localStorage.setItem(KEY,JSON.stringify(db));$('.save-state').innerHTML='<i></i> 自动保存';updateCounts()}
5	function $(q,r=document){return r.querySelector(q)}function $$(q,r=document){return [...r.querySelectorAll(q)]}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function id(){return crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2)}function story(id){return db.stories.find(s=>s.id===id)}function charObj(id){return db.characters.find(c=>c.id===id)}function charsFor(p){return(p.characters||[]).map(x=>({...charObj(x.id),role:x.role})).filter(c=>c.id)}function dateSort(a,b){return (a.date||'').localeCompare(b.date||'', 'zh-CN',{numeric:true,sensitivity:'base'})}function notify(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
6	function updateCounts(){$('#story-count').textContent=db.stories.length;$('#passage-count').textContent=db.passages.length;$('#link-count').textContent=db.links.length;$('#tab-passage-count').textContent=db.passages.length;$('#tab-story-count').textContent=db.stories.length}
7	function render(){fillFilters();updateCounts();renderTimeline();renderLibrary();renderBoard()}
8	function fillFilters(){const configs=[['filter-story','story','全部故事'],['filter-character','char','全部角色'],['filter-timeline','timeline','全部时间线'],['board-story-filter','story','全部故事'],['board-character-filter','char','全部角色'],['board-timeline-filter','timeline','全部时间线']];configs.forEach(([sel,type,all])=>{const el=$('#'+sel),prior=el.value;let options=[];if(type==='story')options=db.stories.map(s=>[s.id,s.title]);if(type==='char')options=db.characters.map(c=>[c.id,c.name]);if(type==='timeline')options=[...new Set(db.passages.map(p=>p.timeline).filter(Boolean))].map(t=>[t,t]);el.innerHTML=`<option value="all">${all}</option>`+options.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');el.value=options.some(([v])=>v===prior)?prior:'all'})}
9	function filteredPassages(prefix='filter'){let list=[...db.passages],storyF=$('#'+(prefix==='filter'?'filter-story':'board-story-filter')).value,charF=$('#'+(prefix==='filter'?'filter-character':'board-character-filter')).value,timeF=$('#'+(prefix==='filter'?'filter-timeline':'board-timeline-filter')).value;if(storyF!=='all')list=list.filter(p=>p.storyId===storyF);if(charF!=='all')list=list.filter(p=>(p.characters||[]).some(c=>c.id===charF));if(timeF!=='all')list=list.filter(p=>p.timeline===timeF);return list}
10	function renderTimeline(){const list=filteredPassages().sort(dateSort),track=$('#timeline-track');$('#timeline-result').textContent=`显示 ${list.length} 个 clips`;$('#timeline-range').textContent=list.length?(list[0].date||'未标时间')+' — '+(list.at(-1).date||'未标时间'):'NO ENTRIES YET';if(!list.length){track.style.width='100%';track.innerHTML='<div class="time-axis"></div><div class="timeline-empty">还没有符合条件的 clips</div>';$('#timeline-list').innerHTML=emptyHTML('时间线上还没有 clips','在码字页添加一个分节，再为它设置发生时间。','＋');return}const n=list.length,width=Math.max(700,Math.min(1450,160+(n-1)*155));track.style.width=width+'px';let html='<div class="time-axis"></div>';const ticks=Math.min(6,n);for(let i=0;i<ticks;i++){const ix=Math.round(i*(n-1)/Math.max(1,ticks-1)),x=5+ix/Math.max(1,n-1)*90;html+=`<div class="time-tick" style="left:${x}%" data-date="${esc(list[ix].date||'未标时间')}"></div>`}list.forEach((p,i)=>{const x=n===1?50:5+i/(n-1)*90,above=i%2===0?'above':'below';html+=`<button class="time-node ${above}" style="left:${x}%" data-edit="${p.id}" aria-label="${esc(p.title)}"><span class="node-dot"></span><span class="node-card"><b>${esc(p.title)}</b><small>${esc(p.date||'时间待补')} · ${esc(story(p.storyId)?.title||'未归档')}</small></span></button>`});track.innerHTML=html;track.onclick=e=>{const node=e.target.closest('[data-edit]');if(node)openPassage(node.dataset.edit)};$('#timeline-list').innerHTML=list.slice(0,8).map(rowHTML).join('');bindEdit($('#timeline-list'))}
11	function emptyHTML(title,sub,icon='✳'){return`<div class="empty-state"><span class="empty-icon">${icon}</span><strong>${esc(title)}</strong><p>${esc(sub)}</p></div>`}
12	function rowHTML(p){return`<article class="passage-row" data-edit="${p.id}"><span class="row-date">${esc(p.date||'时间待补')}</span><span class="row-main"><b>${esc(p.title||'未命名 clip')}</b><small>${esc(p.timeline||'未设时间线')} · ${charsFor(p).map(c=>esc(c.name)).join('、')||'尚无角色'}</small></span><span class="row-story">${esc(story(p.storyId)?.title||'未归档')}</span></article>`}function bindEdit(root=document){$$('[data-edit]',root).forEach(el=>el.addEventListener('click',()=>openPassage(el.dataset.edit)))}
13	function renderLibrary(){const root=$('#library-content'),query=$('#library-search').value.trim().toLowerCase();if(libraryTab==='stories'){let rows=db.stories.filter(s=>!query||s.title.toLowerCase().includes(query));root.innerHTML=rows.length?rows.map(s=>`<article class="story-card" data-story-edit="${s.id}"><h3>${esc(s.title)}</h3><p>${esc(s.description||'点击编辑故事信息')}</p><div class="story-count"><b>${db.passages.filter(p=>p.storyId===s.id).length}</b>clips</div></article>`).join(''):emptyHTML('还没有故事','先新建一篇故事，再把多个 clips收进来。','▤');$$('[data-story-edit]',root).forEach(el=>el.onclick=()=>editStory(el.dataset.storyEdit));return}let rows=db.passages.filter(p=>{let text=[p.title,p.body,story(p.storyId)?.title,...charsFor(p).map(c=>c.name),...(p.tags||[])].join(' ').toLowerCase();return !query||text.includes(query)}).sort(dateSort);root.innerHTML=rows.length?rows.map(p=>`<article class="library-card" data-edit="${p.id}"><div class="library-card-head"><div><h3>${esc(p.title)}</h3><div class="story-name">${esc(story(p.storyId)?.title||'未归档')}</div></div><div class="date-chip">${esc(p.date||'时间待补')}</div></div>${p.body?`<p class="excerpt">${esc(p.body.slice(0,240))}${p.body.length>240?'…':''}</p>`:''}<div class="library-meta"><span class="tag">${esc(p.timeline||'未设时间线')}</span>${charsFor(p).map(c=>`<span class="tag ${c.role}">${esc(c.name)} · ${c.role==='major'?'主角':'配角'}</span>`).join('')}${(p.tags||[]).map(t=>`<span class="tag"># ${esc(t)}</span>`).join('')}</div></article>`).join(''):emptyHTML('没有找到clips','试试调整关键词，或新建一个 clips。','⌕');bindEdit(root)}
14	function boardPassages(){return filteredPassages('board').sort(dateSort)}
15	function renderBoard(){const canvas=$('#board-canvas'),root=$('#board-nodes'),svg=$('#connections'),list=boardPassages();root.innerHTML='';svg.innerHTML='';$('#board-empty').classList.toggle('hidden',list.length>0);if(!list.length){$('#board-mode').textContent='添加clips后即可整理线索';return}const W=Math.max(canvas.clientWidth,780),H=Math.max(canvas.clientHeight,560),cols=Math.max(2,Math.ceil(Math.sqrt(list.length*W/H))),gapX=Math.min(270,(W-255)/(cols-1||1)),gapY=195;list.forEach((p,i)=>{const col=i%cols,row=Math.floor(i/cols),jitter=(i*37)%25,x=25+col*gapX+jitter,y=26+row*gapY+((i*29)%22);const node=document.createElement('article');node.className='board-card';node.dataset.id=p.id;node.style.left=x+'px';node.style.top=y+'px';node.innerHTML=`<div class="card-meta"><span>${esc(p.date||'时间待补')}</span><span>${esc(p.timeline||'未分类')}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.body||'记录还没有正文…')}</p><div class="card-tags">${charsFor(p).map(c=>`<span class="tag ${c.role}">${esc(c.name)}</span>`).join('')}${(p.tags||[]).slice(0,2).map(t=>`<span class="tag"># ${esc(t)}</span>`).join('')}</div>`;root.append(node);node.onclick=e=>{if(e.detail===2){openPassage(p.id);return}selectBoard(p.id,node)};node.ondblclick=()=>openPassage(p.id)});const totalRows=Math.ceil(list.length/cols);root.style.width=Math.max(W,cols*gapX+270)+'px';root.style.height=Math.max(H,totalRows*gapY+40)+'px';canvas.style.minHeight=Math.max(H,totalRows*gapY+40)+'px';requestAnimationFrame(drawConnections);$('#board-mode').textContent=selectedBoard.length===1?'再选一张卡片，建立关联':'选择两张卡片建立关联'}
16	function selectBoard(pid,node){if(!selectedBoard.length){selectedBoard=[pid];node.classList.add('selected');$('#board-mode').textContent='已选 1 张卡片，请再选一张';return}if(selectedBoard[0]===pid){selectedBoard=[];node.classList.remove('selected');$('#board-mode').textContent='选择两张卡片建立关联';return}const [a,b]=[selectedBoard[0],pid],found=db.links.findIndex(l=>l.a===a&&l.b===b||l.a===b&&l.b===a);if(found>=0){db.links.splice(found,1);notify('已移除这条关联')}else{db.links.push({a,b});notify('已建立clips关联')}selectedBoard=[];save();renderBoard()}
17	function drawConnections(){const svg=$('#connections'),canvas=$('#board-canvas'),r=canvas.getBoundingClientRect();svg.setAttribute('width',canvas.scrollWidth);svg.setAttribute('height',canvas.scrollHeight);svg.setAttribute('viewBox',`0 0 ${canvas.scrollWidth} ${canvas.scrollHeight}`);svg.innerHTML='';db.links.forEach((link,index)=>{const a=$(`.board-card[data-id="${CSS.escape(link.a)}"]`),b=$(`.board-card[data-id="${CSS.escape(link.b)}"]`);if(!a||!b)return;const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect(),ax=ra.left-r.left+canvas.scrollLeft+ra.width/2,ay=ra.top-r.top+canvas.scrollTop+ra.height/2,bx=rb.left-r.left+canvas.scrollLeft+rb.width/2,by=rb.top-r.top+canvas.scrollTop+rb.height/2,line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',ax);line.setAttribute('y1',ay);line.setAttribute('x2',bx);line.setAttribute('y2',by);line.setAttribute('pointer-events','stroke');line.onclick=()=>{db.links.splice(index,1);save();renderBoard();notify('已移除这条关联')};svg.append(line)})}
18	function openPassage(pid=null){if(!db.stories.length&&!pid){createStoryPrompt();return}const p=pid?db.passages.find(x=>x.id===pid):null;$('#modal-title').textContent=p?'编辑clips':'新建clips';$('#entry-id').value=p?.id||'';$('#entry-title').value=p?.title||'';$('#entry-body').value=p?.body||'';$('#entry-date').value=p?.date||'';$('#entry-timeline').value=p?.timeline||'';$('#entry-tags').value=(p?.tags||[]).join('，');$('#entry-story').innerHTML=db.stories.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('');$('#entry-story').value=p?.storyId||db.stories[0]?.id;$('#delete-entry').classList.toggle('hidden',!p);drawCharPicks(p);$('#modal-backdrop').classList.remove('hidden');$('#entry-title').focus()}
19	function drawCharPicks(p){const chosen=new Map((p?.characters||[]).map(c=>[c.id,c.role]));$('#character-picks').innerHTML=db.characters.length?db.characters.map(c=>`<label class="character-pick"><input type="checkbox" value="${c.id}" ${chosen.has(c.id)?'checked':''}><span>${esc(c.name)}</span><em class="${c.kind}">${c.kind==='major'?'主角':'配角'}</em></label>`).join(''):'<small>还没有角色。可在下方添加。</small>'}
20	function addCharacter(){const inp=$('#new-character'),name=inp.value.trim();if(!name)return;let c=db.characters.find(x=>x.name===name);if(!c){c={id:id(),name,kind:$('#new-character-role').value};db.characters.push(c)}inp.value='';drawCharPicks({characters:[...$$('.character-pick input:checked').map(x=>({id:x.value,role:db.characters.find(c=>c.id===x.value)?.kind})),{id:c.id,role:c.kind}]});save()}
21	function closeModal(){$('#modal-backdrop').classList.add('hidden')}
22	function createStoryPrompt(){let title=prompt('先为这篇故事起一个标题：');if(!title?.trim())return;db.stories.push({id:id(),title:title.trim(),description:''});save();render();openPassage()}
23	function editStory(sid){const s=story(sid);if(!s)return;const title=prompt('故事标题',s.title);if(title===null)return;if(!title.trim()){notify('故事标题不能为空');return}s.title=title.trim();const description=prompt('故事简介（可留空）',s.description||'');if(description!==null)s.description=description.trim();save();render()}
24	function addStory(){let title=prompt('故事标题（例如一篇文章的名称）');if(!title?.trim())return;let description=prompt('故事简介（可选）','')||'';db.stories.push({id:id(),title:title.trim(),description:description.trim()});save();render();notify('故事已创建')}
25	function switchView(name){activeView=name;$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+name));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#crumb-current').textContent={timeline:'时间线',board:'线索关系板',library:'故事与clips'}[name];if(name==='board')requestAnimationFrame(drawConnections)}
26	$$('.nav-item').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-switch="library"]').forEach(b=>b.onclick=()=>switchView('library'));$('#add-passage-top').onclick=()=>openPassage();$('#add-story').onclick=addStory;$('#timeline-reset').onclick=()=>{$('#filter-story').value=$('#filter-character').value=$('#filter-timeline').value='all';renderTimeline()};$('#board-filter-toggle').onclick=()=>$('#board-filter').classList.toggle('hidden');$('#clear-selection').onclick=()=>{selectedBoard=[];renderBoard()};['filter-story','filter-character','filter-timeline'].forEach(x=>$('#'+x).onchange=renderTimeline);['board-story-filter','board-character-filter','board-timeline-filter'].forEach(x=>$('#'+x).onchange=renderBoard);$('#library-search').oninput=renderLibrary;$$('.library-tab').forEach(b=>b.onclick=()=>{libraryTab=b.dataset.tab;$$('.library-tab').forEach(x=>x.classList.toggle('active',x===b));renderLibrary()});$('#add-character').onclick=addCharacter;$('#new-character').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addCharacter()}};$('#modal-close').onclick=$('#cancel-entry').onclick=closeModal;$('#modal-backdrop').onclick=e=>{if(e.target===$('#modal-backdrop'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#entry-form').onsubmit=e=>{e.preventDefault();const pid=$('#entry-id').value,title=$('#entry-title').value.trim();if(!title)return;let selected=$$('.character-pick input:checked').map(inp=>{let c=charObj(inp.value);return{id:c.id,role:c.kind}});let p={id:pid||id(),storyId:$('#entry-story').value,title,body:$('#entry-body').value.trim(),date:$('#entry-date').value.trim(),timeline:$('#entry-timeline').value.trim(),characters:selected,tags:$('#entry-tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean)};const at=db.passages.findIndex(x=>x.id===pid);if(at>=0)db.passages[at]=p;else db.passages.push(p);save();closeModal();render();notify(at>=0?'clips已更新':'clips已保存')};$('#delete-entry').onclick=()=>{const...
