28	function renderTimeline(){const list=filteredPassages().sort((a,b)=>{const ap=Number.isFinite(a.position)?a.position:null,bp=Number.isFinite(b.position)?b.position:null;if(ap!==null&&bp!==null)return ap-bp;if(ap!==null)return -1;if(bp!==null)return 1;return dateSort(a,b)}),track=$('#timeline-track');list.forEach((p,i)=>{if(!Number.isFinite(p.position))p.position=i*155});$('#timeline-result').textContent=`显示 ${list.length} 个 clips`;$('#timeline-range').textContent=list.length?(list[0].date||'未标时间')+' — '+(list.at(-1).date||'未标时间'):'NO ENTRIES YET';if(!list.length){track.style.width='100%';track.innerHTML='<div class="time-axis"></div><div class="timeline-empty">还没有符合条件的 clips</div>';$('#timeline-list').innerHTML=emptyHTML('时间线上还没有 clips','在码字页添加一个分节，再为它设置发生时间。','＋');$('#interval-panel').classList.add('hidden');return}const max=Math.max(...list.map(p=>p.position)),width=Math.max(700,max+120);track.style.width=width+'px';let html='<div class="time-axis"></div>';const ticks=Math.min(6,list.length);for(let i=0;i<ticks;i++){const ix=Math.round(i*(list.length-1)/Math.max(1,ticks-1)),x=40+list[ix].position;html+=`<div class="time-tick" style="left:${x}px" data-date="${esc(list[ix].date||'未标时间')}"></div>`}list.forEach((p,i)=>{const above=i%2===0?'above':'below',selected=selectedTimeNodes.includes(p.id)?'selected':'';html+=`<button class="time-node ${above} ${selected}" style="left:${40+p.position}px" data-time-node="${p.id}" aria-label="${esc(p.title)}"><span class="node-dot"></span><span class="node-card"><b>${esc(p.title)}</b><small>${esc(p.date||'时间待补')} · ${esc(story(p.storyId)?.title||'未归档')}</small></span></button>`});track.innerHTML=html;$$('[data-time-node]',track).forEach(node=>{const pid=node.dataset.timeNode;let startX=0,startPos=0,moved=false;node.onpointerdown=e=>{if(e.button!==0)return;startX=e.clientX;startPos=db.passages.find(p=>p.id===pid)?.position||0;moved=false;node.setPointerCapture(e.pointerId)};node.onpointermove=e=>{if(!node.hasPointerCapture(e.poi...
29	function selectTimelineNode(pid){if(selectedTimeNodes.includes(pid)){selectedTimeNodes=selectedTimeNodes.filter(x=>x!==pid)}else{selectedTimeNodes.push(pid);if(selectedTimeNodes.length>2)selectedTimeNodes.shift()}renderTimeline()}
30	function lockedTimeGroup(start){const found=new Set([start]);let changed=true;while(changed){changed=false;for(const r of db.timeRelations||[]){if(!r.locked)continue;if(found.has(r.a)&&!found.has(r.b)){found.add(r.b);changed=true}if(found.has(r.b)&&!found.has(r.a)){found.add(r.a);changed=true}}}return found}
31	function updateIntervalPanel(){const panel=$('#interval-panel');if(selectedTimeNodes.length!==2){panel.classList.add('hidden');return}panel.classList.remove('hidden');const [a,b]=selectedTimeNodes.map(pid=>db.passages.find(p=>p.id===pid));if(!a||!b){selectedTimeNodes=[];panel.classList.add('hidden');return}const relation=(db.timeRelations||[]).find(r=>r.a===a.id&&r.b===b.id||r.a===b.id&&r.b===a.id);$('#interval-title').textContent=`${a.title} ↔ ${b.title}`;$('#interval-subtitle').textContent='设置两个节点之间的时间刻度间隔';$('#interval-distance').value=relation?.distance??Math.max(1,Math.round(Math.abs((b.position||0)-(a.position||0))));$('#interval-locked').checked=!!relation?.locked}
32	function saveInterval(){if(selectedTimeNodes.length!==2)return;const [a,b]=selectedTimeNodes.map(pid=>db.passages.find(p=>p.id===pid));const distance=Math.max(1,Number($('#interval-distance').value)||1);let relation=db.timeRelations.find(r=>r.a===a.id&&r.b===b.id||r.a===b.id&&r.b===a.id);if(!relation){relation={a:a.id,b:b.id,distance,locked:false};db.timeRelations.push(relation)}relation.distance=distance;relation.locked=$('#interval-locked').checked;const anchor=a.position||0;b.position=anchor+distance;save();renderTimeline();notify(relation.locked?'间隔已锁定并保存':'节点间隔已保存')}
33	$('#save-interval').onclick=saveInterval;$('#cancel-interval').onclick=()=>{selectedTimeNodes=[];renderTimeline()};
34	const originalSubmit=$('#entry-form').onsubmit;$('#entry-form').onsubmit=e=>{const pid=$('#entry-id').value,position=db.passages.find(p=>p.id===pid)?.position,known=new Set(db.passages.map(p=>p.id));originalSubmit(e);if(pid&&Number.isFinite(position)){const updated=db.passages.find(p=>p.id===pid);if(updated){updated.position=position;save();renderTimeline()}}else if(!pid){const added=db.passages.find(p=>!known.has(p.id));if(added){added.position=Math.max(-155,...db.passages.map(p=>Number.isFinite(p.position)?p.position:-155))+155;save();renderTimeline()}}};
35	const originalDelete=$('#delete-entry').onclick;$('#delete-entry').onclick=()=>{const pid=$('#entry-id').value;originalDelete();if(!db.passages.some(p=>p.id===pid)){db.timeRelations=db.timeRelations.filter(r=>r.a!==pid&&r.b!==pid);selectedTimeNodes=selectedTimeNodes.filter(x=>x!==pid);save()}};
36	let activeStoryId=db.stories[0]?.id||null,writerSaveTimer=null;
37	function storyClips(sid){return db.passages.filter(p=>p.storyId===sid).sort((a,b)=>Number.isFinite(a.order)&&Number.isFinite(b.order)?a.order-b.order:db.passages.indexOf(a)-db.passages.indexOf(b))}
38	function writerBodyMarkup(text=''){if(!text)return '';return String(text).split(/\n/).map(line=>`<div>${esc(line)||'<br>'}</div>`).join('')}
39	function caretTextOffset(editor,selection){const text=editor.innerText.replace(/\r/g,'');if(!selection?.rangeCount||!editor.contains(selection.anchorNode))return text.length;const range=document.createRange();range.selectNodeContents(editor);range.setEnd(selection.anchorNode,selection.anchorOffset);const measure=document.createElement('div');measure.style.cssText='position:fixed;left:-10000px;top:0;visibility:hidden;white-space:pre-wrap';measure.append(range.cloneContents());document.body.append(measure);const offset=measure.innerText.replace(/\r/g,'').length;measure.remove();return Math.min(offset,text.length)}
