245	function serpentineCoords(list, rowW) {
246	  const capacity = Math.max(1, Math.floor((rowW + 40) / 200));
247	  const rows = [];
248	  for (let i = 0; i < list.length; i += capacity) rows.push(list.slice(i, i + capacity));
249	  const coords = new Map();
250	  rows.forEach((rowClips, r) => {
251	    const count = rowClips.length;
252	    const dir = r % 2 === 0 ? 1 : -1;             // 偶数行左→右，奇数行右→左
253	    const ordered = dir === 1 ? rowClips : [...rowClips].reverse();
254	    ordered.forEach((p, j) => {
255	      const x = dir === 1 ? 40 + (j + 0.5) * rowW / count : 40 + rowW - (j + 0.5) * rowW / count;
256	      coords.set(p.id, { x, y: r * ROW_H + 120 });
257	    });
258	  });
259	  return { coords, rowCount: rows.length };
260	}
