277	/* --- 蛇形展开布局：1 单位 = tlZoom px（与收起模式同距），超宽自然换行（奇数行镜像） --- */
278	function serpentineCoords(list, rowW) {
279	  const coords = new Map();
280	  if (!list.length) return { coords, rowCount: 0 };
281	  const left = 60, right = 40 + rowW;
282	  const scale = tlExpanded ? tlZoom : 1;
283	  let row = 0, dir = 1;
284	  list.forEach(p => {
285	    const baseX = left + p.position * scale;
286	    if (baseX > right) { row++; dir = -dir; }     // 超出右缘 → 换行并镜像方向
287	    coords.set(p.id, { x: dir === 1 ? baseX : left + right - baseX, y: row * ROW_H + 120, row });
288	  });
289	  return { coords, rowCount: row + 1, scale };
290	}
