310	function expandedDropPosition(selfId, dropLeft, dropTop) {
311	  const placed = filteredPassages().filter(p => Number.isFinite(p.position)).sort((a, b) => a.position - b.position);
312	  const scroll = $('#timeline-scroll');
313	  const rowW = Math.max(420, scroll.clientWidth - 120);
314	  const { coords, rowCount } = serpentineCoords(placed, rowW);
315	  const tail = () => Math.max(0, (placed.length ? Math.max(...placed.map(p => p.position)) : 0) + 160);
316	  const rRaw = Math.round((dropTop - 120) / ROW_H);
317	  if (rRaw >= rowCount) return { position: tail(), row: rowCount };   // 拖到末行之外 → 排到时间线最后
318	  const r = clamp(rRaw, 0, rowCount - 1);
319	  const rowY = r * ROW_H + 120;
320	  const rowClips = placed
321	    .filter(p => p.id !== selfId && Math.abs(coords.get(p.id).y - rowY) < 1)
322	    .sort((a, b) => coords.get(a.id).x - coords.get(b.id).x);
323	  if (!rowClips.length) return { position: tail(), row: r };
324	  const xs = rowClips.map(p => coords.get(p.id).x);
325	  const ps = rowClips.map(p => p.position);
326	  const gaps = ps.slice(1).map((v, i) => v - ps[i]).filter(g => g > 0);
327	  const gap = gaps.length ? gaps.reduce((s, g) => s + g, 0) / gaps.length : 160;
328	  const idx = xs.findIndex(x => x > dropLeft);
329	  let position;
330	  if (idx === -1) position = ps[ps.length - 1] + gap;
331	  else if (idx === 0) position = Math.max(0, ps[0] - gap);
332	  else position = (ps[idx - 1] + ps[idx]) / 2;
333	  return { position, row: r };
334	}
